		@Override
		public void registerHints(RuntimeHints hints, @Nullable ClassLoader classLoader) {
			for (JavaVersion javaVersion : JavaVersion.values()) {
				hints.reflection().registerType(javaVersion.versionSpecificClass);
			}
		}

